import React, { useState, useRef, useCallback, useEffect } from 'react';
import { attendanceAPI } from './api_service';

const CameraRecognition = () => {
  const videoRef = useRef(null);
  const [stream, setStream] = useState(null);
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState("Prêt - Cliquez sur Capturer & Analyser");

  // ================= DÉMARRER LA CAMÉRA =================
  useEffect(() => {
    const startCamera = async () => {
      try {
        setStatus("🎥 Démarrage de la caméra...");
        const mediaStream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: "user", width: 1280, height: 720 }
        });
        setStream(mediaStream);
        if (videoRef.current) {
          videoRef.current.srcObject = mediaStream;
        }
        setStatus("✅ Caméra démarrée avec succès");
        console.log("✅ [ÉTAPE 1] Caméra démarrée");
      } catch (err) {
        setStatus("❌ Impossible d'accéder à la caméra");
        console.error("❌ Erreur caméra:", err);
      }
    };

    startCamera();

    return () => {
      if (stream) stream.getTracks().forEach(track => track.stop());
    };
  }, []);

  // ================= ARRÊTER LA CAMÉRA =================
  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(track => track.stop());
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setStatus("📴 Caméra arrêtée");
    console.log("🛑 [ÉTAPE] Caméra arrêtée par l'utilisateur");
  };

  // ================= CAPTURE + ANALYSE =================
  const handleCapture = useCallback(async () => {
    if (!videoRef.current) {
      setStatus("❌ Caméra non disponible");
      return;
    }

    setLoading(true);

    try {
      // Étape 1 : Capture
      setStatus("📸 Étape 1/4 : Capture de l'image...");
      console.log("📸 [ÉTAPE 1] Capture de l'image en cours...");

      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth || 1280;
      canvas.height = videoRef.current.videoHeight || 720;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(videoRef.current, 0, 0);

      const imageSrc = canvas.toDataURL('image/jpeg', 0.92);
      console.log("📸 [ÉTAPE 1] Image capturée - Taille base64:", imageSrc.length);

      // Étape 2 : Envoi au Backend
      setStatus("🚀 Étape 2/4 : Envoi de l'image au Backend...");
      console.log("🚀 [ÉTAPE 2] Envoi vers /attendance/recognize/");

      const response = await attendanceAPI.recognize(imageSrc);

      // Étape 3 : Réponse reçue
      setStatus("📥 Étape 3/4 : Réponse reçue du Backend...");
      console.log("✅ [ÉTAPE 3] Réponse du Backend :", response);

      const data = response?.data || response || {};

      console.log("📊 [ÉTAPE 4] Données finales :", data);

      // Étape 4 : Résultat final
      const name = String(data.student || data.student_name || data.name || "Inconnu");
      const confidence = (Number(data.confidence || 0) * 100).toFixed(1);

      if (data.success || name !== "Inconnu") {
        setStatus(`✅ Étape 4/4 : Succès ! ${name} - Confiance : ${confidence}%`);
      } else {
        setStatus(`⚠️ Étape 4/4 : ${String(data.message || data.error || "Visage non reconnu")}`);
      }
    } catch (err) {
      console.error("❌ Erreur complète :", err);
      const errorMsg = err.response?.data?.error || err.message || "Erreur serveur";
      setStatus(`❌ Erreur - ${errorMsg}`);
    } finally {
      setLoading(false);
    }
  }, []);

  return (
    <div style={{ padding: '40px', maxWidth: '850px', margin: '0 auto', textAlign: 'center' }}>
      <h1 style={{ marginBottom: '30px' }}>📷 Reconnaissance Faciale</h1>

      <div style={{ 
        borderRadius: '16px', 
        overflow: 'hidden', 
        background: '#000', 
        marginBottom: '30px',
        boxShadow: '0 10px 40px rgba(0,0,0,0.3)'
      }}>
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted
          style={{ width: '100%', height: 'auto', display: 'block' }}
        />
      </div>

      <div style={{ display: 'flex', gap: '15px', marginBottom: '30px' }}>
        <button 
          onClick={handleCapture}
          disabled={loading}
          style={{
            flex: 1,
            padding: '16px',
            fontSize: '17px',
            background: loading ? '#6b7280' : '#4F46E5',
            color: 'white',
            border: 'none',
            borderRadius: '10px',
            cursor: loading ? 'not-allowed' : 'pointer',
            fontWeight: '600'
          }}
        >
          {loading ? '⏳ Analyse en cours...' : '🔍 Capturer & Analyser'}
        </button>

        <button 
          onClick={stopCamera}
          style={{
            flex: 1,
            padding: '16px',
            fontSize: '17px',
            background: '#EF4444',
            color: 'white',
            border: 'none',
            borderRadius: '10px',
            cursor: 'pointer',
            fontWeight: '600'
          }}
        >
          🛑 Arrêter la Caméra
        </button>
      </div>

      {status && (
        <div style={{
          padding: '25px',
          borderRadius: '12px',
          fontSize: '19px',
          minHeight: '80px',
          backgroundColor: status.includes('✅') ? '#DCFCE7' : '#FEE2E2',
          color: status.includes('✅') ? '#166534' : '#991B1B',
          border: `3px solid ${status.includes('✅') ? '#86EFAC' : '#FECACA'}`
        }}>
          {status}
        </div>
      )}

      <p style={{ marginTop: '40px', color: '#64748B', fontSize: '15px' }}>
        Chemin suivi : Caméra → Capture → Envoi Backend → Pipeline (InsightFace) → Résultat
      </p>
    </div>
  );
};

export default CameraRecognition;
